import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.DbKnw1Aw.js";const k=JSON.parse('{"title":"API","description":"","frontmatter":{},"headers":[],"relativePath":"api.md","filePath":"api.md","lastUpdated":1794389918000}'),i={name:"api.md"};function s(h,t,c,r,n,l){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h1><p>所有接口都是 <code>GET</code> 请求，参数放在查询字符串里，需要 URL 编码。</p><h2 id="生成配置" tabindex="-1">生成配置 <a class="header-anchor" href="#生成配置" aria-label="Permalink to &quot;生成配置&quot;">​</a></h2><h3 id="clash-与-singbox" tabindex="-1"><code>/clash</code> 与 <code>/singbox</code> <a class="header-anchor" href="#clash-与-singbox" aria-label="Permalink to &quot;`/clash` 与 `/singbox`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>返回</th><th>Content-Type</th></tr></thead><tbody><tr><td><code>/clash</code></td><td>Clash（mihomo）YAML 配置</td><td><code>text/yaml; charset=utf-8</code></td></tr><tr><td><code>/singbox</code></td><td>sing-box JSON 配置</td><td><code>application/json; charset=utf-8</code></td></tr></tbody></table><table tabindex="0"><thead><tr><th>参数</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>config</code></td><td>是</td><td>节点链接或 <code>http(s)://</code> 订阅地址，多个用换行分隔</td></tr><tr><td><code>selectedRules</code></td><td>否</td><td>预设名（<code>minimal</code> / <code>balanced</code> / <code>comprehensive</code>），或 JSON 数组形式的分类标识，例如 <code>[&quot;Google&quot;,&quot;Location:CN&quot;]</code>。数组按给出的顺序生成规则；缺省或无法解析时使用 <code>minimal</code></td></tr><tr><td><code>customRules</code></td><td>否</td><td>JSON 数组形式的自定义规则，见下文</td></tr><tr><td><code>pin</code></td><td>否</td><td><code>true</code> 时自定义规则排在分类规则之前</td></tr><tr><td><code>name</code></td><td>否</td><td>订阅名，客户端导入时显示的配置名，默认 <code>Sublink</code>，最长 64 个字符。通过响应头 <code>Content-Disposition</code> 与 <code>profile-title</code> 返回，非 ASCII 名称分别用 <code>filename*=UTF-8&#39;&#39;</code> 和 <code>base64:</code> 前缀编码</td></tr></tbody></table><p>分类标识见<a href="./guide/rules#_18-个分类">规则分类</a>。缺少 <code>config</code> 时返回 <code>400 Missing config parameter</code>。</p><h4 id="customrules" tabindex="-1">customRules <a class="header-anchor" href="#customrules" aria-label="Permalink to &quot;customRules&quot;">​</a></h4><p>每条规则是一个对象，所有字段都是字符串，多个值用逗号分隔：</p><table tabindex="0"><thead><tr><th>字段</th><th>对应规则</th></tr></thead><tbody><tr><td><code>name</code></td><td>出站。<code>DIRECT</code> / <code>REJECT</code> 直接指向内置出站；其他名称会新建同名策略组</td></tr><tr><td><code>domain</code></td><td>完整域名（Clash <code>DOMAIN</code>，sing-box <code>domain</code>），可省略</td></tr><tr><td><code>domain_suffix</code></td><td>域名后缀</td></tr><tr><td><code>domain_keyword</code></td><td>域名关键词</td></tr><tr><td><code>ip_cidr</code></td><td>IP 段</td></tr><tr><td><code>site</code></td><td>Geo-Site 分类名</td></tr><tr><td><code>ip</code></td><td>Geo-IP 分类名</td></tr><tr><td><code>protocol</code></td><td>协议，仅 sing-box 生效</td></tr></tbody></table><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;site&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ip&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;DIRECT&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;domain_suffix&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;domain_keyword&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ip_cidr&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;10.0.0.0/8&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;protocol&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><h3 id="xray" tabindex="-1"><code>/xray</code> <a class="header-anchor" href="#xray" aria-label="Permalink to &quot;`/xray`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>config</code></td><td>是</td><td>同上</td></tr></tbody></table><p>拉取其中的订阅并与节点链接合并，返回 Base64 编码的节点列表（每行一个节点）。响应的 Content-Type 为 <code>application/json; charset=utf-8</code>，这是沿用原项目的行为，内容本身是纯文本 Base64。</p><h2 id="短链" tabindex="-1">短链 <a class="header-anchor" href="#短链" aria-label="Permalink to &quot;短链&quot;">​</a></h2><table tabindex="0"><thead><tr><th>接口</th><th>说明</th></tr></thead><tbody><tr><td><code>/shorten-v2?url=&lt;订阅链接&gt;&amp;shortCode=&lt;路径&gt;</code></td><td>保存 <code>url</code> 的查询参数，返回纯文本路径。<code>shortCode</code> 省略时随机生成 7 位；已存在的路径会被覆盖</td></tr><tr><td><code>/c/:code</code></td><td>302 跳转到 <code>/clash?&lt;保存的参数&gt;</code></td></tr><tr><td><code>/b/:code</code></td><td>302 跳转到 <code>/singbox?&lt;保存的参数&gt;</code></td></tr><tr><td><code>/x/:code</code></td><td>302 跳转到 <code>/xray?&lt;保存的参数&gt;</code></td></tr><tr><td><code>/shorten?url=&lt;完整链接&gt;</code></td><td>旧版接口：保存完整链接，返回 <code>{&quot;shortUrl&quot;: &quot;.../s/&lt;code&gt;&quot;}</code></td></tr><tr><td><code>/s/:code</code></td><td>旧版接口：302 跳转到保存的完整链接，不存在时返回 <code>404 Short URL not found</code></td></tr></tbody></table><p>短链存储在 KV 中，不设过期时间。</p><h2 id="前端辅助接口" tabindex="-1">前端辅助接口 <a class="header-anchor" href="#前端辅助接口" aria-label="Permalink to &quot;前端辅助接口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>接口</th><th>说明</th></tr></thead><tbody><tr><td><code>/api/rules</code></td><td>返回 <code>{ rules, presets }</code>：每个分类的 <code>name</code>、<code>outbound</code>、<code>site_rules</code>、<code>default_outbound</code>，以及三个预设包含的分类</td></tr><tr><td><code>/api/geosite/:name</code></td><td>返回 MetaCubeX 中该分类已展开的纯文本域名名单（<code>+.</code> 开头为后缀，其余为完整域名），边缘缓存 1 天；分类不存在返回 404，名称不合法返回 400</td></tr></tbody></table>',19)])])}const u=d(i,[["render",s]]);export{k as __pageData,u as default};
